PROGRAM ST310_OVERLAMNING
VAR
    steg        : INT := 0;
    tmrAck      : TON;
    trigReset   : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
END_VAR

trigReset(CLK := SYS_RESET);

(* Ett brutet nodstopp kraver manuell kvittering. EMG_OK lases bara. *)
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Griptkraften utanfor 40 till 260 N nar mottagaren haller: antingen har
   greppet slappt eller sa klammer den sonder detaljen. *)
IF ST320_GRP_CLOSED AND (ST320_GRP_FRC < 40.0 OR ST320_GRP_FRC > 260.0) THEN
    xLarm := TRUE;
END_IF;

(* Tidsovervakning pa kvittensen: mottagaren ska svara inom 3,0 s. *)
tmrAck(IN := ST310_HSK_REQ AND NOT ST310_HSK_ACK, PT := T#3s);
IF tmrAck.Q THEN
    xLarm := TRUE;
END_IF;

IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND ST310_ZON_FREE
               AND NOT xLarm AND NOT xKravOmstart;

IF NOT xDriftsklar THEN
    ST310_RB_START := FALSE;
    ST320_RB_START := FALSE;
    ST310_HSK_REQ := FALSE;
    ST310_HSK_RST := FALSE;
    (* Gripdonen star kvar som de ar: att slappa en detalj darfor att
       zonvakten brots ar precis hur detaljer hamnar pa golvet. *)
    IF NOT EMG_OK OR xLarm THEN
        steg := 0;
    END_IF;
ELSE
    CASE steg OF
        0:
            ST310_GRP_OPEN := FALSE;
            ST320_GRP_CLOSE := FALSE;
            IF ST310_PRT_PRS THEN
                ST310_RB_START := TRUE;
                steg := 1;
            END_IF;
        1:
            IF ST310_RB_DONE THEN
                ST310_RB_START := FALSE;
                ST310_HSK_REQ := TRUE;
                steg := 2;
            END_IF;
        2:
            IF ST310_HSK_ACK THEN
                steg := 3;
            END_IF;
        3:
            ST320_RB_START := TRUE;
            steg := 4;
        4:
            IF ST320_RB_DONE THEN
                ST320_RB_START := FALSE;
                ST320_GRP_CLOSE := TRUE;
                steg := 5;
            END_IF;
        5:
            (* Avlamnaren slapper FORST nar mottagaren bekraftat greppet. *)
            IF ST320_GRP_CLOSED THEN
                ST310_GRP_OPEN := TRUE;
                steg := 6;
            END_IF;
        6:
            IF ST310_GRP_OPENED THEN
                steg := 7;
            END_IF;
        7:
            IF ST310_HSK_DONE THEN
                ST310_HSK_REQ := FALSE;
                ST310_HSK_RST := TRUE;
                steg := 8;
            END_IF;
        8:
            IF NOT ST310_HSK_ACK THEN
                ST310_HSK_RST := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

